CREATE TABLE IF NOT EXISTS command_tasks (id serial PRIMARY KEY, title text NOT NULL, description text, category text NOT NULL DEFAULT 'field', priority text NOT NULL DEFAULT 'normal', status text NOT NULL DEFAULT 'pending', constituency text, ward text, polling_station text, assigned_to text, due_at timestamp, completed_at timestamp, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS field_incidents (id serial PRIMARY KEY, title text NOT NULL, description text, severity text NOT NULL DEFAULT 'medium', status text NOT NULL DEFAULT 'open', constituency text, ward text, polling_station text, latitude text, longitude text, reported_by text, assigned_to text, resolution text, created_at timestamp NOT NULL DEFAULT now(), resolved_at timestamp);
CREATE TABLE IF NOT EXISTS volunteer_checkins (id serial PRIMARY KEY, volunteer_name text NOT NULL, team_name text, ward text, polling_station text, activity_type text NOT NULL DEFAULT 'field_visit', households_reached integer NOT NULL DEFAULT 0, doors_knocked integer NOT NULL DEFAULT 0, notes text, checked_in_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS intelligence_briefs (id serial PRIMARY KEY, title text NOT NULL, brief_type text NOT NULL DEFAULT 'daily', summary text NOT NULL, risk_level text NOT NULL DEFAULT 'low', constituency text, ward text, source_count integer NOT NULL DEFAULT 0, tags jsonb NOT NULL DEFAULT '[]'::jsonb, published boolean NOT NULL DEFAULT false, created_by text, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS command_notifications (id serial PRIMARY KEY, title text NOT NULL, message text NOT NULL, type text NOT NULL DEFAULT 'info', module text, action_url text, recipient_role text, is_read boolean NOT NULL DEFAULT false, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS executive_reports (id serial PRIMARY KEY, title text NOT NULL, report_type text NOT NULL DEFAULT 'weekly', period_start text, period_end text, status text NOT NULL DEFAULT 'draft', summary text, metrics jsonb NOT NULL DEFAULT '{}'::jsonb, created_by text, created_at timestamp NOT NULL DEFAULT now());
